parameters.prompt:
=고객 맞춤 단말기 및 요금제 추천에 활용할 프로모션·이벤트 정보를 검색합니다.

아래 고객 정보와 분석 결과를 바탕으로 고객에게 관련성이 높은 프로모션·이벤트 내용을 검색합니다.

현재 단말기: {{ $json.customer.current_device }}
현재 요금제: {{ $json.customer.current_plan }}
사용 패턴: {{ $json.customer.usage_pattern }}
상담 목적: {{ $json.customer.consultation_goal }}
선호 브랜드: {{ $json.customer.preferred_brand }}
월 예산: {{ $json.customer.target_monthly_budget }}원

고객 분석 요약:
{{ $json.analysis.analysis_summary }}

교체 사유:
{{ $json.analysis.replacement_reason }}

중요 기능:
{{ ($json.analysis.important_features ?? []).join(', ') }}

선호 제품군:
{{ $json.analysis.preferred_product_group }}

추천 고려사항:
{{ ($json.analysis.recommendation_factors ?? []).join(', ') }}

parameters.jsCode:
const base = $('추천 요청 데이터 구성').first().json;

const devices = $('기종 정보 조회')
  .all()
  .map((item) => item.json)
  .filter((d) => d.device_id);

const plans = $('요금제 정보 조회')
  .all()
  .map((item) => item.json)
  .filter((p) => p.plan_id);

const promotions = $('RAG 프로모션, 이벤트 조회')
  .all()
  .map((item) => item.json)
  .filter((item) => Object.keys(item).length > 0);

return [{
  json: {
    ...base,

    product_catalog: {
      devices: devices.map((d) => ({
        device_id: d.device_id,
        device_name: d.device_name,
        manufacturer: d.manufacturer,
        device_price: d.device_price,
      })),

      plans: plans.map((p) => ({
        plan_id: p.plan_id,
        plan_name: p.plan_name,
        monthly_fee: p.monthly_fee,
        allowance_info: p.allowance_info,
      })),
    },

    promotion_context: promotions.map((p) => ({
      content: p.pageContent ?? p.content ?? p.text ?? null,
      metadata: p.metadata ?? {},
      document_id: p.document_id ?? p.metadata?.document_id ?? null,
    })),
  },
}];

const input = $input.first().json;

return [
  {
    json: {
      ...input,
      recommendation_context: {
        request: input.recommendation_request ?? '기기·요금제 추천',
        customer: input.customer ?? {},
        consultation: input.consultation ?? {},
        analysis: input.analysis ?? {},
      },
    },
  },
];

